    private CodigoErro erroDe(ResumoPedidoRequest request) {
        return assertThatThrownBy(() -> calculadora.calcular(request))
                .isInstanceOf(CheckoutException.class)
                .extracting(excecao -> ((CheckoutException) excecao).getCodigo())
                .asInstanceOf(org.assertj.core.api.InstanceOfAssertFactories.type(CodigoErro.class))
                .actual();
    }

    private List<ItemRequest> itensCom(ItemRequest item) {
        List<ItemRequest> itens = new ArrayList<>();
        itens.add(item);
        return itens;
    }
